-- Only administrators may approve verified coach/team affiliation; moderators may reject.
CREATE OR REPLACE FUNCTION public.admin_review_coach_team_request(p_request_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare r public.coach_team_requests%rowtype; c public.coaches%rowtype; allowed boolean; t public.teams%rowtype; begin select public.is_current_user_admin_or_moderator() into allowed; if not coalesce(allowed,false) then raise exception 'Admin access required'; end if; if p_status not in ('approved','rejected') then raise exception 'Invalid status'; end if; if p_status='approved' and not exists (select 1 from public.admin_roles ar where ar.user_id=(select auth.uid()) and lower(trim(coalesce(ar.role,'')))='admin') then raise exception 'Only admins may approve coach verification' using errcode='42501'; end if; select * into r from public.coach_team_requests where id=p_request_id for update; if not found then raise exception 'Request not found'; end if; update public.coach_team_requests set status=p_status, reviewer_id=auth.uid(), reviewer_note=p_note, reviewed_at=now() where id=p_request_id; if p_status='approved' then select * into t from public.teams where id=r.team_id; select * into c from public.coaches where id=(select coach_profile_id from public.profiles where id=r.user_id); if c.id is null then insert into public.coaches(name,country,city,source,active) select coalesce(display_name,'HoopCheck Coach'),t.country,t.city,'HoopCheck verified coach',true from public.profiles where id=r.user_id returning * into c; update public.profiles set coach_profile_id=c.id,coach_verified=true,coach_verified_at=coalesce(coach_verified_at,now()) where id=r.user_id; end if; update public.coaches set current_team_id=r.team_id,country=t.country,city=t.city,active=true where id=c.id; update public.coach_team_assignments set active=false,end_date=current_date where coach_id=c.id and active=true; insert into public.coach_team_assignments(coach_id,team_id,role,season,start_date,active) values(c.id,r.team_id,coalesce(r.requested_role,'Coach'),'2026-27',current_date,true); update public.profiles set current_team=t.name,current_country=t.country where id=r.user_id; end if; return true; end; $function$;

revoke all on function public.admin_review_coach_team_request(uuid,text,text) from public,anon;
grant execute on function public.admin_review_coach_team_request(uuid,text,text) to authenticated,service_role;
